steps.script:
$o=@{files=@();guard=@{}}
foreach($n in @('titulares.log','tendencias.log','ttittulares-mobile-trigger.log','ttendencias-mobile-trigger.log')){
 $p=Join-Path 'C:\TTiTTulares' $n
 if(-not (Test-Path $p)){continue}
 $tail=@(Get-Content $p -Tail 230 -ErrorAction SilentlyContinue)
 $counts=@{}
 foreach($tag in @('TOO_MANY_TABS','OTHER_CHAT_ACTIVITY','DRAFT_NOT_VERIFIED','COMPOSER_NOT','NO_EDITOR','GUARD','ERROR','DEFERRED','RUN','SENT','confirmed','sending','PREFLIGHT','NO PROGRESS')){
 $counts[$tag]=@($tail|Where-Object {$_ -like ('*'+$tag+'*')}).Count
 }
 $o.files+=@{name=$n;updated=(Get-Item $p).LastWriteTimeUtc.ToString('o');counts=$counts;recentStates=@($tail|Where-Object{$_ -match 'TOO_MANY_TABS|OTHER_CHAT_ACTIVITY|PREFLIGHT|RETRY DEFERRED|GUARD ABORT|EDITORIAL RETRY' }|Select-Object -Last 6|ForEach-Object{($_ -replace '\d{12,}','[id]') -replace 'https?://\S+','[URL]'})}
}
$p='C:\TTiTTulares\TT-Editorial-Guard.js'
if(Test-Path $p){$s=Get-Content -LiteralPath $p -Raw -ErrorAction SilentlyContinue;$o.guard=@{size=$s.Length;has18=$s.Contains("if(pages.length>18)fail('TOO_MANY_TABS");has40=$s.Contains("pages.length>40");last=(Get-Item $p).LastWriteTimeUtc.ToString('o')}}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress -Depth 5))
